def fibonacci():
    fib = [0, 1]
    for i in range(2, 15):
        fib.append(fib[i-1] + fib[i-2])
    return fib

def string_crescente():
    texto = ""
    caracteres = ['a', 'b', 'c', 'd', 'e']
    for char in caracteres:
        texto += char
    return texto

def multiplicacao_aninhada():
    produto = 1
    fatores = [1, 2, 3, 4, 5]
    for num in fatores:
        produto *= num
    return produto

def bubble_sort():
    arr = [5, 3, 8, 6, 7, 2]
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def caminho_grafo():
    grafo = {0: [1, 2], 1: [3], 2: [4], 3: [], 4: []}
    caminho = [0]
    atual = 0
    while grafo[atual]:
        proximo = grafo[atual].pop()
        caminho.append(proximo)
        atual = proximo
    return caminho

def fatorial_recursivo(n=5):
    if n == 0:
        return 1
    else:
        return n * fatorial_recursivo(n-1)

def torre_hanoi(n=3):
    movimentos = []
    def mover(de, para):
        movimentos.append(f"{de}→{para}")
    def resolver(n, origem, destino, auxiliar):
        if n > 0:
            resolver(n-1, origem, auxiliar, destino)
            mover(origem, destino)
            resolver(n-1, auxiliar, destino, origem)
    resolver(n, 'A', 'C', 'B')
    return movimentos

def markov_chain():
    matriz = [[0.9, 0.1], [0.5, 0.5]]
    estado = [1, 0]
    historico = []
    for _ in range(10):
        novo_estado = [0, 0]
        for i in range(2):
            for j in range(2):
                novo_estado[j] += estado[i] * matriz[i][j]
        estado = novo_estado
        historico.append(estado.copy())
    return historico

def caminho_critico():
    atividades = {
        'A': {'duracao': 2, 'dependencias': []},
        'B': {'duracao': 3, 'dependencias': ['A']},
        'C': {'duracao': 1, 'dependencias': ['B']}
    }
    tempos = {}
    for atv in ['A', 'B', 'C']:
        if not atividades[atv]['dependencias']:
            tempos[atv] = atividades[atv]['duracao']
        else:
            tempos[atv] = max(tempos[dep] for dep in atividades[atv]['dependencias']) + atividades[atv]['duracao']
    return tempos

def gauss_seidel(A=[[4,1],[1,3]], b=[1,2], iteracoes=5):
    n = len(b)
    x = [0] * n
    for _ in range(iteracoes):
        for i in range(n):
            soma = sum(A[i][j] * x[j] for j in range(n) if j != i)
            x[i] = (b[i] - soma) / A[i][i]
    return x

def fechamento_transitivo(grafo={'A':['B'],'B':['C'],'C':[]}):
    fechamento = {k: set(v) for k, v in grafo.items()}
    for k in grafo:
        for i in grafo:
            if k in fechamento[i]:
                fechamento[i].update(fechamento[k])
    return fechamento

def compressao_rle():
    texto = "AAABBBCCCDDDD"
    comprimido = []
    count = 1
    for i in range(1, len(texto)):
        if texto[i] == texto[i-1]:
            count += 1
        else:
            comprimido.append((texto[i-1], count))
            count = 1
    comprimido.append((texto[-1], count))
    return comprimido

def gerador_mandelbrot():
    resultados = []
    for y in range(-10, 11):
        linha = []
        for x in range(-20, 21):
            c = complex(x/10, y/10)
            z = 0
            for _ in range(20):
                z = z**2 + c
                if abs(z) > 2:
                    break
            linha.append(abs(z))
        resultados.append(linha)
    return resultados

